{"file_text": "/* Chat Layout */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    border-right: 1px solid #333;
    overflow-y: auto;
}

/* Main message area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #222529;
    min-width: 0;
}

/* Thread panel */
.chat-thread {
    width: 25%;
    min-width: 280px;
    background: #1e2126;
    border-left: 1px solid #333;
    display: flex;
    flex-direction: column;
}

/* Channel List */
.channel-list {
    padding: 1rem;
}

.channel-list-title {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #999;
    margin-bottom: 0.75rem;
}

::deep .channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #2c2f33;
}

::deep .channel-item.active {
    background: #3a3d42;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #888;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: #e74c3c;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 2px 6px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

::deep .message-area-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #333;
    background: #2a2d31;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 0.2rem 0 0;
    font-size: 0.8rem;
    color: #999;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
}

::deep .loading-indicator {
    text-align: center;
    color: #888;
    padding: 0.5rem;
    font-size: 0.85rem;
}

/* Message Item */
::deep .message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    margin-bottom: 0.25rem;
    position: relative;
    transition: background 0.15s;
}

::deep .message-item:hover {
    background: #2c2f33;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 700;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #777;
}

::deep .message-content {
    color: #ddd;
    font-size: 0.9rem;
    margin-top: 0.15rem;
    line-height: 1.4;
}

/* Reactions */
::deep .message-reactions {
    display: flex;
    gap: 0.4rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #3a3d42;
    border: 1px solid #555;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #4a4d52;
}

/* Thread link */
::deep .thread-link {
    background: none;
    border: none;
    color: #4a9eff;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.25rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message actions (hover) */
::deep .message-actions {
    position: absolute;
    top: 0.25rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2a2d31;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 0.2rem;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #aaa;
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    cursor: pointer;
}

::deep .action-btn:hover {
    background: #3a3d42;
    color: #fff;
}

