::deep .emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .emoji-btn:hover {
    background: #3a3d42;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border-top: 1px solid #333;
    background: #2a2d31;
    align-items: flex-end;
}

::deep .message-input textarea {
    flex: 1;
