    padding: 0.5rem 0.75rem;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
}

::deep .message-input textarea:focus {
    outline: none;
    border-color: #4a9eff;
}

::deep .send-btn {
    background: #4a9eff;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background: #3a8eee;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
